package com.fasterxml.jackson.core.json.async;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.async.ByteArrayFeeder;
import com.fasterxml.jackson.core.async.NonBlockingInputFeeder;
import com.fasterxml.jackson.core.io.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NonBlockingJsonParser.feedInput
 */
public class NonBlockingJsonParser_feedInput_TriageGen2Test {

    private NonBlockingJsonParser parser;
    private IOContext ioContext;
    private ByteQuadsCanonicalizer sym;

    @Before
    public void setUp() {
        ioContext = IOContext.bootstrap(null);
        sym = ByteQuadsCanonicalizer.newInstance(null);
        parser = new NonBlockingJsonParser(ioContext, 0, sym);
    }

    @Test
    public void testFeedInput_Success() throws Exception {
        byte[] buf = new byte[]{'{', '}'};
        int start = 0;
        int end = 2;

        // Initial state check via reflection to ensure we are starting fresh
        // (Assuming internal state is 0/null initially)

        parser.feedInput(buf, start, end);

        assertEquals(buf, getInternalField("_inputBuffer"));
        assertEquals(start, getInternalField("_inputPtr"));
        assertEquals(end, getInternalField("_inputEnd"));
        assertEquals(end - start, getInternalField("_origBufferLen"));
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_RemainingInput() throws Exception {
        // First feed
        byte[] buf1 = new byte[]{'{'};
        parser.feedInput(buf1, 0, 1);

        // Attempt second feed without consuming the first byte
        // This should trigger _reportError because _inputPtr (0) < _inputEnd (1)
        byte[] buf2 = new byte[]{'}', '}'};
        parser.feedInput(buf2, 0, 2);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_EndBeforeStart() throws Exception {
        byte[] buf = new byte[]{'{', '}'};
        // end (0) < start (1)
        parser.feedInput(buf, 1, 0);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_AlreadyClosed() throws Exception {
        byte[] buf = new byte[]{'{'};
        parser.feedInput(buf, 0, 1);

        // Simulate end of input
        parser.endOfInput();
        setInternalField("_endOfInput", true);

        // Attempt to feed more
        byte[] buf2 = new byte[]{'}', '}'};
        parser.feedInput(buf2, 0, 2);
    }

    @Test
    public void testFeedInput_PointerMathAndRowStart() throws Exception {
        // Setup initial state
        byte[] buf1 = new byte[]{1, 2, 3, 4, 5};
        parser.feedInput(buf1, 0, 5);

        // Use reflection to simulate partially processed state
        setInternalField("_inputPtr", 5);
        setInternalField("_inputEnd", 5);
        setInternalField("_currInputProcessed", 5);
        setInternalField("_origBufferLen", 5);
        setInternalField("_currInputRowStart", 2);

        // Second feed
        byte[] buf2 = new byte[]{6, 7, 8};
        int start2 = 1;
        int end2 = 3;

        parser.feedInput(buf2, start2, end2);

        // _currInputProcessed += _origBufferLen => 5 + 5 = 10
        assertEquals(10, getInternalField("_currInputProcessed"));

        // _currInputRowStart = start - (_inputEnd - _currInputRowStart)
        // start = 1
        // _inputEnd (old) = 5
        // _currInputRowStart (old) = 2
        // calculation: 1 - (5 - 2) = 1 - 3 = -2
        assertEquals(-2, getInternalField("_currInputRowStart"));

        assertEquals(buf2, getInternalField("_inputBuffer"));
        assertEquals(start2, getInternalField("_inputPtr"));
        assertEquals(end2, getInternalField("_inputEnd"));
    }

    // --- Reflection Helpers to access private/protected fields for verification ---

    private Object getInternalField(String fieldName) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(parser);
    }

    private void setInternalField(String fieldName, Object value) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(parser, value);
    }
}
